<?php $adminTitle='Change Password'; require __DIR__.'/_header.php'; $saved=false;$error=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$cfg=owner_config();$current=(string)($_POST['current']??'');$new=(string)($_POST['new']??'');$confirm=(string)($_POST['confirm']??'');if(!password_verify($current,$cfg['password_hash']??''))$error='Current password is incorrect.';elseif(strlen($new)<6)$error='Use at least 6 characters for the new password.';elseif($new!==$confirm)$error='New passwords do not match.';elseif(update_owner_hash(password_hash($new,PASSWORD_DEFAULT)))$saved=true;else$error='Could not update the password file.';} ?>
<div class="admin-title"><div><span>SECURITY</span><h1>Change Owner Password</h1><p>The launch password is intentionally simple because it was specified for setup. Replace it before going live.</p></div></div><?php if($saved):?><div class="success">Password changed successfully.</div><?php endif;?><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?>
